/* prog39_horner.c
 *
 * Re‑implementation of the original program’s behaviour.
 * The original binary is heavily obfuscated; the logic has been
 * recovered by analysing its state‑machine.
 *
 * Behaviour (matches the original binary):
 *
 *   1. If the program receives fewer than 2 arguments (i.e. argc < 2)
 *        prints "NO_INPUT" and exits.
 *
 *   2. The first argument (argv[1]) is interpreted as the integer x.
 *        * If the conversion fails (non‑numeric characters) → "BAD_INPUT".
 *        * If |x| > 10 → "OUT_OF_RANGE".
 *
 *   3. If exactly two arguments are supplied (only x, no coefficients)
 *        prints "EMPTY" and exits.
 *
 *   4. All remaining arguments are interpreted as coefficients of a
 *      polynomial (in the order given).  If any conversion fails → "BAD_INPUT".
 *
 *   5. More than 1000 coefficients are not allowed → "OUT_OF_RANGE".
 *
 *   6. The polynomial is evaluated with Horner's method:
 *
 *           result = 0;
 *           for each coefficient c in order:
 *               result = result * x + c;
 *
 *      The final result is printed as a signed 64‑bit integer followed by a
 *      newline.
 *
 *   7. The program always returns 0.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>

#define MAX_COEFF 1000

/* Parse a string as a signed long long, ensuring the whole string
   is consumed and that the value fits in a long long. */
static int parse_ll(const char *s, long long *out)
{
    char *endptr;
    errno = 0;
    long long val = strtoll(s, &endptr, 10);
    if (errno != 0)               /* overflow / underflow */
        return 0;
    if (endptr == s)              /* no conversion */
        return 0;
    if (*endptr != '\0')          /* extra characters */
        return 0;
    *out = val;
    return 1;
}

int main(int argc, char *argv[])
{
    /* 1. No input */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* 2. Parse x (first argument) */
    long long x;
    if (!parse_ll(argv[1], &x)) {
        puts("BAD_INPUT");
        return 0;
    }

    /* 2b. Range check: |x| must be <= 10 */
    if (x > 10 || x < -10) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* 3. No coefficients supplied */
    if (argc == 2) {
        puts("EMPTY");
        return 0;
    }

    /* 4‑5. Parse coefficients, checking count and validity */
    long long coeffs[MAX_COEFF];
    int coeff_cnt = 0;
    for (int i = 2; i < argc; ++i) {
        if (coeff_cnt >= MAX_COEFF) {
            puts("OUT_OF_RANGE");
            return 0;
        }
        long long v;
        if (!parse_ll(argv[i], &v)) {
            puts("BAD_INPUT");
            return 0;
        }
        coeffs[coeff_cnt++] = v;
    }

    /* 6. Horner evaluation */
    long long result = 0;
    for (int i = 0; i < coeff_cnt; ++i) {
        result = result * x + coeffs[i];
    }

    printf("%lld\n", result);
    return 0;
}
